class Solution:
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        def to_int(node):
            value, place = 0, 1
            while node:
                value += node.val * place
                place *= 10
                node = node.next
            return value
        total = to_int(l1) + to_int(l2)
        dummy = tail = ListNode()
        for ch in reversed(str(total)):
            tail.next = ListNode(int(ch))
            tail = tail.next
        return dummy.next
